/**
 * Extract Manifest URL - Normalize webhook data structure
 * Handles both webhook body structure (first pass) and direct fields (Wait node resume)
 * FIX: Check top-level first (Wait node), then body (webhook), process ALL items
 * Handle null values properly - construct from orderId if manifestUrl is null
 */
const inputs = $input.all();

return inputs.map(item => {
  const input = item.json;

  // Priority: Check top-level first (Wait node resume), then body (webhook first pass)
  // Wait node data has manifestUrl at top level, webhook has it in body
  // Handle null/empty string explicitly
  let manifestUrl = (input.manifestUrl && input.manifestUrl !== null && input.manifestUrl !== '') ? input.manifestUrl : null;
  if (!manifestUrl) {
    manifestUrl = (input.originalManifestUrl && input.originalManifestUrl !== null && input.originalManifestUrl !== '') ? input.originalManifestUrl : null;
  }

  let orderId = (input.orderId && input.orderId !== null && input.orderId !== '') ? input.orderId : null;
  if (!orderId) {
    orderId = (input.amazonOrderId && input.amazonOrderId !== null && input.amazonOrderId !== '') ? input.amazonOrderId : null;
  }

  // Fallback: Extract orderId from manifestKey if available (S3 node might have stripped orderId)
  if ((!orderId || orderId === null || orderId === '') && input.manifestKey) {
    const manifestKeyStr = String(input.manifestKey).trim();
    if (manifestKeyStr && manifestKeyStr !== 'null' && manifestKeyStr !== 'undefined') {
      // Try multiple patterns: /orders/{orderId}/ or orders/{orderId}/
      const patterns = [
        /[\/]orders[\/]([^\/]+)[\/]/,  // Matches /orders/TEST-ORDER-006/
        /orders[\/]([^\/]+)[\/]/,     // Matches orders/TEST-ORDER-006/
      ];

      for (const pattern of patterns) {
        const keyMatch = manifestKeyStr.match(pattern);
        if (keyMatch && keyMatch[1]) {
          orderId = keyMatch[1];
          console.log(`✓ Extracted orderId from manifestKey: ${orderId} (pattern matched)`);
          break;
        }
      }

      if (!orderId) {
        console.warn(`⚠️ Could not extract orderId from manifestKey: ${manifestKeyStr.substring(0, 100)}`);
      }
    }
  }

  let webhookUrl = (input.webhookUrl && input.webhookUrl !== null && input.webhookUrl !== '') ? input.webhookUrl : null;

  // If not found at top level, check body (webhook structure)
  if (!manifestUrl && input.body && input.body !== input) {
    manifestUrl = (input.body.manifestUrl && input.body.manifestUrl !== null && input.body.manifestUrl !== '') ? input.body.manifestUrl : null;
    if (!manifestUrl) {
      manifestUrl = (input.body.originalManifestUrl && input.body.originalManifestUrl !== null && input.body.originalManifestUrl !== '') ? input.body.originalManifestUrl : null;
    }
    if (!orderId) {
      orderId = (input.body.orderId && input.body.orderId !== null && input.body.orderId !== '') ? input.body.orderId : null;
      if (!orderId) {
        orderId = (input.body.amazonOrderId && input.body.amazonOrderId !== null && input.body.amazonOrderId !== '') ? input.body.amazonOrderId : null;
      }
    }
    if (!webhookUrl) {
      webhookUrl = (input.body.webhookUrl && input.body.webhookUrl !== null && input.body.webhookUrl !== '') ? input.body.webhookUrl : null;
    }
  }

  // If no manifestUrl but we have orderId, construct it
  // This handles the case where manifestUrl is explicitly null (from Restore JSON After Upload)
  if ((!manifestUrl || manifestUrl === null || manifestUrl === '') && orderId && orderId !== null && orderId !== '') {
    // PRODUCTION URL: https://admin.littleherolabs.com
    // PREVIEW URL: https://387cb69b.little-hero-labs-admin.pages.dev (for testing preview branches)
    const baseUrl = 'https://admin.littleherolabs.com/api/manifests';
    manifestUrl = `${baseUrl}/book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2a-manifest.json`;
    console.log(`✓ Constructed manifestUrl from orderId: ${manifestUrl} (orderId was: ${orderId})`);
  }

  // Final validation - if still no manifestUrl, we have a problem
  if (!manifestUrl || manifestUrl === null || manifestUrl === '') {
    const keys = input ? Object.keys(input).join(', ') : 'no input';
    const manifestUrlValue = input.manifestUrl;
    const orderIdValue = orderId;  // Use the extracted orderId, not input.orderId
    const manifestKeyValue = input.manifestKey || 'not present';
    console.error(`❌ Cannot resolve manifestUrl. manifestUrl=${manifestUrlValue}, orderId=${orderIdValue}, manifestKey=${manifestKeyValue}, Keys: ${keys}`);
    throw new Error(`Cannot resolve manifestUrl. manifestUrl=${manifestUrlValue}, orderId=${orderIdValue}, manifestKey=${manifestKeyValue}, Keys: ${keys}`);
  }

  // CRITICAL: Detect if this is from webhook (first pass) or Wait node (retry loop)
  // On webhook: body.webhookUrl exists, isFirstPass is undefined
  // On Wait node resume: isFirstPass is explicitly false (from Restore JSON After Upload)
  let isFirstPass = input.isFirstPass;
  if (isFirstPass === undefined) {
    // Not set yet - check if this is from webhook (first pass) or Wait node (retry loop)
    // Check for webhookUrl in body (webhook structure) or top-level (already extracted)
    const hasWebhookUrl = !!(webhookUrl || (input.body && input.body !== input && input.body.webhookUrl));
    isFirstPass = hasWebhookUrl ? true : false; // Default to false if we can't determine
  }

  // CRITICAL: Preserve all fields from input, especially isFirstPass, statusUrl, etc.
  // These are essential for routing in the IF node after retry loops
  return {
    json: {
      ...input,  // Preserve ALL fields from input
      manifestUrl: manifestUrl,
      originalManifestUrl: manifestUrl,
      orderId: orderId || input.orderId || input.amazonOrderId || null,
      webhookUrl: webhookUrl || input.webhookUrl || null,
      // Explicitly preserve these critical fields for IF node routing
      isFirstPass: isFirstPass,
      statusUrl: input.statusUrl || input.status_url || null,
      status_url: input.status_url || input.statusUrl || null,
      requestId: input.requestId || input.request_id || null,
      request_id: input.request_id || input.requestId || null,
      poseNumber: input.poseNumber || null,
      characterHash: input.characterHash || null
    }
  };
});

/**
 * Preserve isFirstPass - Merge manifest with preserved metadata
 * HTTP Request node outputs only the downloaded manifest JSON, overwriting input fields.
 * This node retrieves isFirstPass and other critical metadata from Extract Manifest URL
 * and merges them with the manifest before passing to Parse Submissions.
 */
const inputs = $input.all();
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

// Retrieve isFirstPass and other metadata from Extract Manifest URL
let preservedMetadata = null;
try {
  // Try current run index first
  const extractItems = $items('Extract Manifest URL', 0, runIx);
  if (extractItems && Array.isArray(extractItems) && extractItems.length > 0) {
    preservedMetadata = extractItems[0]?.json || {};
    console.log(`✓ Retrieved metadata from Extract Manifest URL (runIndex ${runIx})`);
  }
} catch (e) {
  console.warn(`⚠️ Could not retrieve from Extract Manifest URL (runIndex ${runIx}): ${e.message}`);
  // Try previous run index as fallback
  try {
    const extractItems = $items('Extract Manifest URL', 0, runIx - 1);
    if (extractItems && Array.isArray(extractItems) && extractItems.length > 0) {
      preservedMetadata = extractItems[0]?.json || {};
      console.log(`✓ Retrieved metadata from Extract Manifest URL (runIndex ${runIx - 1})`);
    }
  } catch (e2) {
    console.warn(`⚠️ Could not retrieve from Extract Manifest URL (runIndex ${runIx - 1}): ${e2.message}`);
  }
}

// Process each input item (should be 1 item with the manifest)
return inputs.map(item => {
  const manifest = item.json || {};

  // Extract preserved metadata
  const isFirstPass = preservedMetadata?.isFirstPass !== undefined ? preservedMetadata.isFirstPass : true;
  const manifestUrl = preservedMetadata?.manifestUrl || preservedMetadata?.originalManifestUrl || null;
  const orderId = preservedMetadata?.orderId || preservedMetadata?.amazonOrderId || null;
  const webhookUrl = preservedMetadata?.webhookUrl || null;
  const statusUrl = preservedMetadata?.statusUrl || preservedMetadata?.status_url || null;
  const requestId = preservedMetadata?.requestId || preservedMetadata?.request_id || null;

  console.log(`📋 Preserved metadata: isFirstPass=${isFirstPass}, manifestUrl=${manifestUrl ? 'present' : 'null'}, orderId=${orderId || 'null'}`);

  // Merge manifest with preserved metadata
  return {
    json: {
      ...manifest,  // The downloaded manifest JSON
      // Overlay with preserved metadata
      isFirstPass: isFirstPass,
      manifestUrl: manifestUrl,
      originalManifestUrl: manifestUrl,
      orderId: orderId,
      webhookUrl: webhookUrl,
      statusUrl: statusUrl,
      status_url: statusUrl,
      requestId: requestId,
      request_id: requestId
    }
  };
});

/**
 * Parse Submissions - Extract approved poses from 2A manifest
 * NEW: Works with manifest-based input and handles retry scenarios
 * FIX: Added isFirstPass flag to track execution context (first pass vs retry loop)
 */
const input = $input.first().json;

// Handle both direct manifest and webhook body wrapper
const body = input.body || input;
let manifest = body.manifest || body;

// If manifest is missing (e.g., from Wait node retry), try to get it from preserved data
if (!manifest || !manifest.schema) {
  // Try to get manifest from preserved fields (from Store Submission Result)
  manifest = input.manifest || null;

  // If still missing, try to get manifestUrl and download it
  if (!manifest || !manifest.schema) {
    const manifestUrl = input.manifestUrl || body.manifestUrl || null;
    if (manifestUrl) {
      // Note: We can't download here in Code node, but we can log the URL
      console.warn(`⚠️ Manifest missing, but manifestUrl found: ${manifestUrl}`);
      console.warn(`⚠️ This workflow needs to download manifest from: ${manifestUrl}`);
      throw new Error(`Manifest missing. Please ensure 'Download 2A Manifest' node runs before Parse Submissions. Manifest URL: ${manifestUrl}`);
    } else {
      throw new Error(`Invalid manifest: missing or invalid. Input keys: ${Object.keys(input || {}).join(', ')}`);
    }
  }
}

// Validate manifest schema
if (manifest.schema !== 'lhb.run-manifest@v2.0') {
  throw new Error(`Invalid manifest schema: ${manifest.schema || 'missing'}`);
}

console.log('=== WORKFLOW 2B STARTED ===');
console.log(`Order: ${manifest.order.orderId}`);
console.log(`Character Hash: ${manifest.characterHash}`);
console.log(`Total poses: ${manifest.poses.total}`);
console.log(`Approved poses: ${manifest.poses.approved}`);

// Extract webhook URL from trigger (for backend callback)
// Note: Environment variables are not accessible in Code nodes, so webhookUrl must be passed in the request body
const webhookUrl = body.webhookUrl || input.webhookUrl;

if (!webhookUrl) {
  console.warn('⚠️ No webhookUrl provided in trigger or environment');
}

// Detect execution context: first pass (from webhook) vs retry loop (from Wait 90 Seconds)
// FIX: isFirstPass is now preserved by "Preserve isFirstPass" node (between Download 2A Manifest and Parse Submissions)
// The Preserve isFirstPass node retrieves it from Extract Manifest URL and merges it with the manifest
// On first pass: isFirstPass will be true (from Extract Manifest URL)
// On retry loop: isFirstPass will be false (from Restore JSON After Upload → Extract Manifest URL)
// Simply use isFirstPass from input (set by Preserve isFirstPass node)
const isFirstPass = input.isFirstPass !== undefined ? input.isFirstPass : true; // Default to true if not set (shouldn't happen)

console.log(`📋 Execution context detection:`);
console.log(`  - input.isFirstPass: ${input.isFirstPass}`);
console.log(`  - Final isFirstPass: ${isFirstPass}`);
console.log(`📋 Execution context: ${isFirstPass ? 'FIRST PASS' : 'RETRY LOOP'}`);

// Extract only approved poses
const approvedPoses = manifest.entries.filter(entry => entry.approved && entry.status === 'approved');

if (approvedPoses.length === 0) {
  throw new Error('No approved poses found in manifest');
}

console.log(`Processing ${approvedPoses.length} approved poses`);
console.log(`Webhook callback: ${webhookUrl || 'NOT SET'}`);

// Return each approved pose as separate item
// Check manifest entries for existing Bria processing status (for retry detection)
const posesWithStatus = approvedPoses.filter(p => p.briaStatusUrl || p.briaRequestId).length;
const posesWithoutStatus = approvedPoses.length - posesWithStatus;
console.log(`📊 Bria status in manifest: ${posesWithStatus} poses have status, ${posesWithoutStatus} poses need submission`);

return approvedPoses.map(pose => {
  // Check if manifest entry has Bria processing info (from previous run)
  const hasBriaStatus = !!(pose.briaStatusUrl || pose.briaRequestId);
  const statusUrl = pose.briaStatusUrl || input.status_url || input.statusUrl || null;
  const requestId = pose.briaRequestId || input.request_id || input.requestId || null;

  if (hasBriaStatus) {
    console.log(`✓ Pose ${pose.poseNumber}: Already has Bria status (${statusUrl ? 'has statusUrl' : 'no statusUrl'})`);
  } else {
    console.log(`⚠ Pose ${pose.poseNumber}: No Bria status in manifest - will submit to Bria`);
  }

  return {
    json: {
      poseNumber: pose.poseNumber,
      originalImageUrl: pose.publicUrl,  // Use publicUrl from manifest (handles retries correctly)
      characterHash: manifest.characterHash,
      orderId: manifest.order.orderId || manifest.order.amazonOrderId,
      manifest: manifest,  // Keep full manifest for later
      manifestUrl: body.manifestUrl || input.manifestUrl || null,  // Preserve manifestUrl for retry scenarios
      webhookUrl: webhookUrl,  // Pass through for final webhook
      // CRITICAL FIX: Prioritize pose-specific statusUrl (from pose.briaStatusUrl) over input.statusUrl
      // This ensures each pose gets its unique statusUrl instead of all poses sharing the same one
      // Priority: pose-specific statusUrl > input statusUrl (from retry loop) > null
      statusUrl: statusUrl || input.statusUrl || input.status_url || null,
      status_url: statusUrl || input.status_url || input.statusUrl || null,
      requestId: requestId || input.requestId || input.request_id || null,
      request_id: requestId || input.request_id || input.requestId || null,
      retryCount: input.retryCount || 0,
      maxRetries: input.maxRetries || 5,
      // Execution context flag: true on first pass (from webhook), false on retry loops
      // CRITICAL: Preserve isFirstPass from input if it's already false (from retry loop)
      isFirstPass: isFirstPass
    }
  };
});

/**
 * Parse Bria status responses (one output item per input item)
 * Works with merged items where Bria fields are top-level.
 * Preserves poseNumber and characterHash from your data.
 */

const inputs = $input.all();

const DONE = new Set(['COMPLETED', 'SUCCESS']);
const WORKING = new Set(['IN_PROGRESS', 'PROCESSING', 'PENDING']);

const now = new Date().toISOString();

return inputs.map(item => {
  const j = item.json ?? {};

  // --- Read Bria status/URL from either top-level or nested result ---
  const status =
    j.status ?? j.state ?? j.result?.status ?? 'UNKNOWN';

  const resultUrl =
    j.result?.image_url ??
    j.result_url ??
    j.url ??
    j.output_url ??
    null;

  // --- Request ID: prefer explicit fields, else parse from statusUrl ---
  let requestId = j.requestId ?? j.request_id ?? j.id ?? null;
  if (!requestId && typeof j.statusUrl === 'string') {
    const m = j.statusUrl.match(/\/status\/([^/?#]+)/);
    if (m) requestId = m[1];
  }

  // --- Retry bookkeeping from your item ---
  const currentRetry = Number(j.retryCount ?? 0);
  const maxRetries   = Number(j.maxRetries ?? 5);

  const shouldDownload = DONE.has(status) && !!resultUrl;
  const shouldRetry    = WORKING.has(status) && currentRetry < maxRetries;

  // --- Preserve your poseNumber and characterHash ---
  const poseNumber = j.poseNumber ?? j.currentPoseNumber ?? null;

  // Keep original characterHash unless it is missing/"nohash"
  let characterHash = j.characterHash ?? null;
  if (!characterHash || characterHash === 'nohash') {
    characterHash = j.orderData?.characterHash ?? characterHash;
  }

  return {
    json: {
      ...j,                  // keep everything you already had (orderData, etc.)
      requestId,
      briaStatus: status,
      resultUrl,
      shouldDownload,
      shouldRetry,
      retryCount: shouldRetry ? currentRetry + 1 : currentRetry,
      maxRetries,
      poseNumber,
      characterHash,
      statusCheckedAt: now,
    },
  };
});

/**
 * Prepare for R2 Upload (multi-item, no cross-workflow refs)
 * Output file path:
 *   book-mvp-simple-adventure/order-generated-assets/characters/{hash}/characters_{hash}_pose{XX}_nobg.png
 */
const items = $input.all();

const BASE_PREFIX = 'book-mvp-simple-adventure/order-generated-assets/characters';
// UPDATE: Removed hardcoded PUBLIC_BASE - S3 node handles uploads directly (works with private R2)
// If publicUrl is needed for external access later, use signed URL API instead

function isBadHash(h) {
  return !h || typeof h !== 'string' || h === 'nohash' || h === 'unknown' || h.trim().length < 4;
}

// try to recover hash from an asset URL if needed
function hashFromUrl(u) {
  if (!u) return null;
  try {
    const p = new URL(u).pathname;
    // matches .../characters/<hash>/...
    return p.match(/\/characters\/([^/]+)\//i)?.[1] ?? null;
  } catch {
    // if it's a path string without host
    return String(u).match(/characters\/([^/]+)\//i)?.[1] ?? null;
  }
}

function getBinary(item) {
  const bin = item.binary || {};
  if (!Object.keys(bin).length) return { key: null, data: null };
  const pref = ['data', 'image', 'file'];
  const key = pref.find(k => bin[k]) || Object.keys(bin)[0];
  return { key, data: bin[key] || null };
}

const out = items.map((item, idx) => {
  const j = item.json || {};

  const poseNumber = Number(j.poseNumber ?? j.currentPoseNumber ?? (idx + 1)) || (idx + 1);

  // Resolve characterHash from local fields first
  let candidateHash =
    j.characterHash ??
    j.orderData?.characterHash ??
    hashFromUrl(j.publicUrl || j.r2Path || j.imageUrl || j.originalImageUrl);

  // If not found, try to retrieve from earlier nodes (Parse Status Response, Merge, or Check Bria Status)
  if (isBadHash(candidateHash)) {
    const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

    // Try Parse Status Response first (most recent before HTTP Request)
    try {
      const parseStatusItems = $items('Parse Status Response', 0, runIx);
      if (parseStatusItems && Array.isArray(parseStatusItems) && parseStatusItems.length > 0) {
        // Since poseNumber might be null, use array index matching
        let matchingItem = null;
        if (idx < parseStatusItems.length) {
          matchingItem = parseStatusItems[idx];
        }
        // Also try to find by poseNumber if it exists
        if (!matchingItem || !matchingItem.json?.characterHash) {
          const foundByPose = parseStatusItems.find(item => {
            const itemPose = item?.json?.poseNumber ?? null;
            return itemPose !== null && itemPose === poseNumber;
          });
          if (foundByPose?.json?.characterHash) {
            matchingItem = foundByPose;
          }
        }
        if (matchingItem?.json?.characterHash) {
          candidateHash = matchingItem.json.characterHash;
          console.log(`✓ Retrieved characterHash from Parse Status Response (item ${idx}): ${candidateHash}`);
        }
      }
    } catch (e) {
      console.warn(`⚠️ Could not retrieve from Parse Status Response: ${e.message}`);
    }

    // Fallback to Merge node (combines original data with status check)
    if (isBadHash(candidateHash)) {
      try {
        const mergeItems = $items('Merge', 0, runIx);
        if (mergeItems && Array.isArray(mergeItems) && mergeItems.length > 0 && idx < mergeItems.length) {
          const mergeItem = mergeItems[idx];
          if (mergeItem?.json?.characterHash) {
            candidateHash = mergeItem.json.characterHash;
            console.log(`✓ Retrieved characterHash from Merge (item ${idx}): ${candidateHash}`);
          }
        }
      } catch (e) {
        console.warn(`⚠️ Could not retrieve from Merge: ${e.message}`);
      }
    }

    // Final fallbacks: Check Bria Status and Parse Submissions (original item data)
    if (isBadHash(candidateHash)) {
      try {
        const checkStatusItems = $items('Check Bria Status', 0, runIx);
        if (checkStatusItems && Array.isArray(checkStatusItems) && checkStatusItems.length > 0 && idx < checkStatusItems.length) {
          const checkItem = checkStatusItems[idx];
          if (checkItem?.json?.characterHash) {
            candidateHash = checkItem.json.characterHash;
            console.log(`✓ Retrieved characterHash from Check Bria Status (item ${idx}): ${candidateHash}`);
          }
        }
      } catch (e) {
        console.warn(`⚠️ Could not retrieve from Check Bria Status: ${e.message}`);
      }
    }

    // Ultimate fallback: Parse Submissions (definitely has characterHash from manifest)
    if (isBadHash(candidateHash)) {
      try {
        const parseSubItems = $items('Parse Submissions', 0, runIx);
        if (parseSubItems && Array.isArray(parseSubItems) && parseSubItems.length > 0 && idx < parseSubItems.length) {
          const parseItem = parseSubItems[idx];
          if (parseItem?.json?.characterHash) {
            candidateHash = parseItem.json.characterHash;
            console.log(`✓ Retrieved characterHash from Parse Submissions (item ${idx}): ${candidateHash}`);
          }
        }
      } catch (e) {
        console.warn(`⚠️ Could not retrieve from Parse Submissions: ${e.message}`);
      }
    }
  }

  const characterHash = isBadHash(candidateHash) ? null : candidateHash;
  if (!characterHash) {
    throw new Error(`Missing characterHash for pose ${poseNumber} (item ${idx})`);
  }

  const { key: binKey, data: binaryData } = getBinary(item);
  if (!binaryData) {
    throw new Error(`No binary data for pose ${poseNumber} (item ${idx})`);
  }

  const paddedPose = String(poseNumber).padStart(2, '0');
  const fileName = `characters_${characterHash}_pose${paddedPose}_nobg.png`;
  const r2Path = `${BASE_PREFIX}/${characterHash}/${fileName}`;
  // NOTE: publicUrl removed - S3 node handles uploads directly (works with private R2)
  // If URL is needed for external access, use signed URL API in downstream nodes
  const publicUrl = null;

  console.log(`[Pose ${poseNumber}] ✓ Prepared upload → ${r2Path}`);

  return {
    json: {
      ...j,
      poseNumber,
      characterHash,
      fileName,
      r2Path,
      publicUrl,
      processedWithBria: true,
      processingError: false,
      downloadedAt: new Date().toISOString(),
    },
    binary: {
      // keep same key so your actual uploader node can see it
      [binKey]: binaryData,
    },
  };
});

return out;

/**
 * Clean up binary after upload (multi-item)
 * Emits only JSON metadata for Workflow 3 consumption.
 */
const items = $input.all();

const out = items.map((it) => {
  const j = it.json || {};
  const poseNumber = j.poseNumber;

  console.log(`[Pose ${poseNumber}] ✓ Uploaded to R2: ${j.r2Path}`);

  return {
    json: {
      poseNumber,
      characterHash: j.characterHash,
      fileName: j.fileName,
      r2Path: j.r2Path,
      publicUrl: j.publicUrl,
      briaProcessed: true,
      briaStatus: j.briaStatus || 'COMPLETED',
      uploadComplete: true,
      uploadedAt: new Date().toISOString(),
      orderData: j.orderData || null,
      sourcePayload: j.sourcePayload || null,
    },
    // No `binary` here on purpose — this "cleans" it.
  };
});

return out;

// Calculate exponential backoff delay
const item = $input.first().json;
const retryCount = item.retryCount || 0;

// Exponential backoff: 30s, 60s, 120s, 240s, 480s
const baseDelay = 30;
const delay = baseDelay * Math.pow(2, retryCount);

console.log(`Retry ${retryCount + 1}: Waiting ${delay} seconds...`);

return [{
  json: {
    ...item,
    retryCount: retryCount + 1,
    delaySeconds: delay
  }
}];

/**
 * Max retries exceeded - mark as failed but include in manifest
 */
const item = $input.first().json;
const poseNumber = item.poseNumber;

console.error(`[Pose ${poseNumber}] ❌ Max retries (${item.maxRetries}) exceeded`);

return [{
  json: {
    poseNumber: poseNumber,
    characterHash: item.characterHash,
    orderId: item.orderId,
    manifest: item.manifest,  // Keep manifest reference
    briaProcessed: false,
    briaStatus: 'MAX_RETRIES_EXCEEDED',
    processingError: true,
    error: `Maximum retry attempts (${item.maxRetries}) exceeded`,
    uploadComplete: false,  // Mark as not uploaded
    needsReview: true
  }
}];

/**
 * Merge - Preserve original item metadata from Has statusUrl? before HTTP Request overwrote it
 * HTTP Request nodes overwrite input JSON with response JSON, losing poseNumber, characterHash, etc.
 * This node retrieves original items from Has statusUrl? and merges them with Bria API responses
 */
const briaResponses = $input.all();
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

// Retrieve original items from Has statusUrl? (before Check Bria Status overwrote them)
let originalItems = [];
try {
  const hasStatusItems = $items('Has statusUrl?', 0, runIx); // TRUE output (index 0)
  if (hasStatusItems && Array.isArray(hasStatusItems) && hasStatusItems.length > 0) {
    originalItems = hasStatusItems.map(item => item.json || {});
    console.log(`✓ Retrieved ${originalItems.length} original item(s) from Has statusUrl?`);
  }
} catch (e) {
  console.warn(`⚠️ Could not retrieve items from Has statusUrl?: ${e.message}`);
}

// If we couldn't retrieve original items, try to extract metadata from Bria response
// (Bria responses might have some metadata in meta fields)
if (originalItems.length === 0 && briaResponses.length > 0) {
